import React from 'react'

const Button = (props) => {
    return (
        <><button style={
            {
                padding: "10px 20px", outline: "none",
                border: "none", boxShadow: "0 0 2px black",
                borderRadius: "5px", background: props.bg
            }
        } onClick={() => props.handleClick}>
            {props.text}
        </button>
        </>
    )
}

export default Button
